static void d3d9_object_record_checks(void)
{
    IDirect3DStateBlock9 *baseline,*block;check(SUCCEEDED(CALL(CreateStateBlock)(device,D3DSBT_ALL,&baseline)),"object baseline");
    IDirect3DVertexBuffer9 *vb,*got_vb;IDirect3DIndexBuffer9 *ib,*got_ib;IDirect3DTexture9 *texture;IDirect3DCubeTexture9 *cube;IDirect3DVolumeTexture9 *volume;IDirect3DBaseTexture9 *got_texture;IDirect3DVertexShader9 *vs,*got_vs;IDirect3DPixelShader9 *ps,*got_ps;IDirect3DVertexDeclaration9 *decl,*old_decl,*got_decl;
    static const DWORD vertex[]={0xfffe0101u,1,0xc00f0000u,0x90e40000u,0xffffu},fragment[]={0xffff0101u,1,0x800f0000u,0x90e40000u,0xffffu};
    const D3DVERTEXELEMENT9 elements[]={{0,0,D3DDECLTYPE_FLOAT3,D3DDECLMETHOD_DEFAULT,D3DDECLUSAGE_POSITION,0},D3DDECL_END()};
    check(SUCCEEDED(CALL(CreateVertexBuffer)(device,64,0,0,D3DPOOL_SYSTEMMEM,&vb,NULL))&&SUCCEEDED(CALL(CreateIndexBuffer)(device,32,0,D3DFMT_INDEX16,D3DPOOL_SYSTEMMEM,&ib,NULL)),"object buffers");check(SUCCEEDED(CALL(CreateTexture)(device,2,2,1,0,D3DFMT_A8R8G8B8,D3DPOOL_MANAGED,&texture,NULL))&&SUCCEEDED(CALL(CreateCubeTexture)(device,2,1,0,D3DFMT_A8R8G8B8,D3DPOOL_MANAGED,&cube,NULL))&&SUCCEEDED(CALL(CreateVolumeTexture)(device,2,2,2,1,0,D3DFMT_A8R8G8B8,D3DPOOL_MANAGED,&volume,NULL)),"object textures");check(SUCCEEDED(CALL(CreateVertexShader)(device,vertex,&vs))&&SUCCEEDED(CALL(CreatePixelShader)(device,fragment,&ps))&&SUCCEEDED(CALL(CreateVertexDeclaration)(device,elements,&decl))&&SUCCEEDED(CALL(CreateVertexDeclaration)(device,elements,&old_decl)),"object programs");
    check(SUCCEEDED(CALL(SetStreamSource)(device,1,NULL,0,0))&&SUCCEEDED(CALL(SetIndices)(device,NULL))&&SUCCEEDED(CALL(SetTexture)(device,0,NULL))&&SUCCEEDED(CALL(SetTexture)(device,1,NULL))&&SUCCEEDED(CALL(SetTexture)(device,260,NULL)),"object seed bindings");check(SUCCEEDED(CALL(SetVertexShader)(device,NULL))&&SUCCEEDED(CALL(SetPixelShader)(device,NULL))&&SUCCEEDED(CALL(SetVertexDeclaration)(device,old_decl)),"object seed shaders");
    Light old_light,recorded;ZeroMemory(&old_light,sizeof(old_light));old_light.Type=D3DLIGHT_DIRECTIONAL;old_light.Direction.z=1;old_light.Diffuse.r=.75f;recorded=old_light;recorded.Diffuse.r=.125f;check(SUCCEEDED(CALL(SetLight)(device,37,&old_light))&&SUCCEEDED(CALL(LightEnable)(device,37,TRUE)),"object seed light");
    UINT offset,stride;DWORD fvf;BOOL active;d3d9_scalar_barrier();check(SUCCEEDED(CALL(BeginStateBlock)(device)),"object begin");
    check(SUCCEEDED(CALL(SetStreamSource)(device,1,vb,4,12))&&SUCCEEDED(CALL(SetStreamSource)(device,1,vb,4,12))&&SUCCEEDED(CALL(SetIndices)(device,ib)),"record object buffers");check(SUCCEEDED(CALL(SetTexture)(device,0,(void*)texture))&&SUCCEEDED(CALL(SetTexture)(device,0,(void*)cube))&&SUCCEEDED(CALL(SetTexture)(device,0,(void*)texture))&&SUCCEEDED(CALL(SetTexture)(device,1,(void*)cube))&&SUCCEEDED(CALL(SetTexture)(device,260,(void*)volume)),"record texture kind replacement");check(SUCCEEDED(CALL(SetVertexShader)(device,vs))&&SUCCEEDED(CALL(SetPixelShader)(device,ps))&&SUCCEEDED(CALL(SetVertexDeclaration)(device,decl)),"record object shaders");check(SUCCEEDED(CALL(SetLight)(device,37,&recorded))&&SUCCEEDED(CALL(LightEnable)(device,37,FALSE))&&SUCCEEDED(CALL(LightEnable)(device,3001,FALSE)),"record sparse lights");
    check(SUCCEEDED(CALL(GetStreamSource)(device,1,&got_vb,&offset,&stride))&&!got_vb,"object live VB");check(SUCCEEDED(CALL(GetIndices)(device,&got_ib))&&!got_ib,"object live IB");for(unsigned i=0;i<3;++i){check(SUCCEEDED(CALL(GetTexture)(device,i==2?260:i,&got_texture))&&!got_texture,"object live textures");}check(SUCCEEDED(CALL(GetVertexShader)(device,&got_vs))&&!got_vs&&SUCCEEDED(CALL(GetPixelShader)(device,&got_ps))&&!got_ps,"object live shaders");check(SUCCEEDED(CALL(GetFVF)(device,&fvf))&&fvf==0,"object live format");check(SUCCEEDED(CALL(GetVertexDeclaration)(device,&got_decl))&&got_decl==old_decl,"object live declaration");IDirect3DVertexDeclaration9_Release(got_decl);Light got;check(SUCCEEDED(CALL(GetLight)(device,37,&got))&&got.Diffuse.r==.75f&&SUCCEEDED(CALL(GetLightEnable)(device,37,&active))&&active,"object live known light");check(FAILED(CALL(GetLight)(device,3001,&got)),"recorded default light does not appear live");
    check(FAILED(CALL(EndStateBlock)(device,NULL)),"object invalid End output");check(FAILED(CALL(BeginStateBlock)(device)),"invalid End leaves recording active");d3d9_scalar_barrier();check(SUCCEEDED(CALL(EndStateBlock)(device,&block)),"object End");d3d9_scalar_barrier();
    check(IDirect3DVertexDeclaration9_Release(old_decl)==1,"live original declaration retained");
    check(IDirect3DVertexBuffer9_Release(vb)==1&&IDirect3DIndexBuffer9_Release(ib)==1,"block retains exactly one buffer ref");check(IDirect3DTexture9_Release(texture)==1&&IDirect3DCubeTexture9_Release(cube)==1&&IDirect3DVolumeTexture9_Release(volume)==1,"block retains one texture ref");check(IDirect3DVertexShader9_Release(vs)==1&&IDirect3DPixelShader9_Release(ps)==1&&IDirect3DVertexDeclaration9_Release(decl)==1,"block retains one program ref");check(SUCCEEDED(IDirect3DStateBlock9_Apply(block)),"object Apply");d3d9_scalar_barrier();
    check(SUCCEEDED(CALL(GetStreamSource)(device,1,&got_vb,&offset,&stride))&&got_vb==vb&&offset==4&&stride==12,"object applied VB");IDirect3DVertexBuffer9_Release(got_vb);check(SUCCEEDED(CALL(GetIndices)(device,&got_ib))&&got_ib==ib,"object applied IB");IDirect3DIndexBuffer9_Release(got_ib);check(SUCCEEDED(CALL(GetTexture)(device,260,&got_texture))&&got_texture==(void*)volume,"object applied vertex volume");IDirect3DBaseTexture9_Release(got_texture);check(SUCCEEDED(CALL(GetVertexShader)(device,&got_vs))&&got_vs==vs&&SUCCEEDED(CALL(GetPixelShader)(device,&got_ps))&&got_ps==ps,"object applied shaders");IDirect3DVertexShader9_Release(got_vs);IDirect3DPixelShader9_Release(got_ps);check(SUCCEEDED(CALL(GetVertexDeclaration)(device,&got_decl))&&got_decl==decl,"object applied declaration");IDirect3DVertexDeclaration9_Release(got_decl);check(SUCCEEDED(CALL(GetLight)(device,37,&got))&&got.Diffuse.r==.125f&&SUCCEEDED(CALL(GetLightEnable)(device,37,&active))&&!active,"object applied known light");check(SUCCEEDED(CALL(GetLight)(device,3001,&got))&&got.Type==D3DLIGHT_DIRECTIONAL&&got.Direction.z==1&&got.Diffuse.r==1,"object applied default sparse light");
    check(SUCCEEDED(IDirect3DStateBlock9_Capture(block))&&SUCCEEDED(IDirect3DStateBlock9_Capture(block)),"object repeated Capture refs");IDirect3DStateBlock9_Release(block);check(SUCCEEDED(CALL(GetVertexShader)(device,&got_vs))&&got_vs==vs,"object live binding retains shader");IDirect3DVertexShader9_Release(got_vs);
    check(SUCCEEDED(IDirect3DStateBlock9_Apply(baseline)),"object restore baseline");IDirect3DStateBlock9_Release(baseline);check(SUCCEEDED(CALL(LightEnable)(device,3001,FALSE)),"object clear default light");
    report("PASS D3D9 object deferred recording: live queries, exact COM references, texture kinds, VS/PS/declarations, sparse default lights, invalid End retention, Apply, repeated Capture and binding ownership");
}
